import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AccountLookupServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(AccountLookupServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String accountId = req.getParameter("id");
        String fields = req.getParameter("fields");

        // Validate accountId is numeric
        if (accountId == null || !accountId.matches("^[0-9]+$")) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\": \"Invalid account ID\"}");
            return;
        }

        // fields parameter allows selecting which columns to return
        // Expected values: "name", "email", "balance", "name,email", etc.
        if (fields == null || fields.isEmpty()) {
            fields = "name, email";
        }

        // Basic character filter - block obvious attack chars
        if (fields.contains(";") || fields.contains("--") || fields.contains("/*")) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\": \"Invalid field specification\"}");
            return;
        }

        String query = "SELECT " + fields + " FROM accounts WHERE account_id = " + accountId;
        logger.info("Executing query for account: " + accountId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {

            // Set query timeout to prevent long-running queries
            stmt.setQueryTimeout(5);

            ResultSet rs = stmt.executeQuery(query);
            StringBuilder json = new StringBuilder("{\"results\": [");
            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",");
                json.append("{");
                for (int i = 1; i <= colCount; i++) {
                    if (i > 1) json.append(",");
                    json.append("\"").append(meta.getColumnName(i)).append("\":");
                    json.append("\"").append(rs.getString(i)).append("\"");
                }
                json.append("}");
                first = false;
            }
            json.append("]}");

            resp.setContentType("application/json");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            logger.warning("Query failed: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().write("{\"error\": \"Database error\"}");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST endpoint for batch lookups
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }

        // Parse JSON body manually (avoiding dependency on JSON lib)
        String content = body.toString();
        if (!content.contains("\"ids\"")) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\": \"Missing ids field\"}");
            return;
        }

        // Extract ids array - expects format: {"ids": [1,2,3]}
        int start = content.indexOf("[") + 1;
        int end = content.indexOf("]");
        if (start <= 0 || end <= start) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\": \"Malformed ids array\"}");
            return;
        }

        String idsStr = content.substring(start, end);
        String query = "SELECT name, email FROM accounts WHERE account_id IN (" + idsStr + ")";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {
            stmt.setQueryTimeout(5);
            ResultSet rs = stmt.executeQuery(query);
            resp.setContentType("application/json");
            resp.getWriter().write("{\"results\": []}"); // simplified
        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\": \"Database error\"}");
        }
    }
}
